DROP TABLE IF EXISTS `device_inventory`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `device_inventory` (
  `id` int NOT NULL AUTO_INCREMENT,
  `serial_no` varchar(45) DEFAULT NULL,
  `imei` bigint DEFAULT NULL,
  `icc_id` varchar(20) DEFAULT NULL,
  `make` varchar(45) DEFAULT NULL,
  `model` varchar(45) DEFAULT NULL,
  `installation_Date` datetime DEFAULT NULL,
  `esim_active_date` datetime DEFAULT NULL,
  `esim_expire_date` datetime DEFAULT NULL,
  `primary_misdn` varchar(45) DEFAULT NULL,
  `esiim_provider` varchar(45) DEFAULT NULL,
  `fallback_misdn` varchar(45) DEFAULT NULL,
  `distributor_id` int DEFAULT NULL,
  `assignedInstaller` int DEFAULT NULL,
  `device_status` int DEFAULT '0',
  `vehicle_number` varchar(45) DEFAULT NULL,
  `fuel_type` varchar(45) DEFAULT NULL,
  `engine_number` varchar(45) DEFAULT NULL COMMENT 'Chasis Number	Vechile Type\\r\\n			',
  `location_applied_for` varchar(45) DEFAULT NULL,
  `chassis_number` varchar(45) DEFAULT NULL,
  `vehicle_type` varchar(45) DEFAULT NULL,
  `owner_name` varchar(45) DEFAULT NULL,
  `owner_address` varchar(255) DEFAULT NULL,
  `owner_mobile` bigint DEFAULT NULL,
  `driver_name` varchar(45) DEFAULT NULL,
  `driver_mobile` bigint DEFAULT NULL,
  `installation_place` varchar(45) DEFAULT NULL,
  `installed_by` int DEFAULT NULL,
  `registerd_by` varchar(45) DEFAULT NULL,
  `status` tinyint(1) DEFAULT '1',
  `isSIMActivated` tinyint(1) NOT NULL DEFAULT '0',
  `activationDate` date DEFAULT NULL,
  `isInstalled` tinyint(1) NOT NULL DEFAULT '0',
  `InstallationDate` date DEFAULT NULL,
  `upl_ac` varchar(255) DEFAULT NULL,
  `upl_fc` varchar(255) DEFAULT NULL,
  `vehicle_registration_date` varchar(20) DEFAULT NULL,
  `owner_aadhaar` varchar(45) DEFAULT NULL,
  `owner_id` int DEFAULT NULL,
  `edit_status` tinyint(1) DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=18307 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `device_inventory`
